"SELECT DISTINCT \nA.[CLAIM_ID]        AS \"Claim ID\",\nCASE\n    WHEN A.[SNF Indicator] = 'Yes' AND B.[Clean Indicator] = 'Clean' AND A.[SLA Age] <= 14  THEN 'Yes'\n    WHEN A.[SNF Indicator] = 'Yes' AND B.[Clean Indicator] = 'Clean' AND A.[SLA Age] > 14 THEN 'No'\nEND                 AS \"SNF Clean Claim Processed Timely\",\nCASE\n    WHEN B.[Clean Indicator] = 'Clean' AND A.[SLA Age] <= 30  THEN 'Yes'\n    WHEN B.[Clean Indicator] = 'Clean' AND A.[SLA Age] > 30 THEN 'No'\nEND                 AS \"Clean Claim Processed Timely\",\nCASE\n    WHEN A.[SLA Age] <= 60  THEN 'Yes'\n    WHEN A.[SLA Age] > 60 THEN 'No'\nEND                 AS \"All Claim Processed Timely\",\nCASE\n    WHEN B.[Clean Indicator] = 'Clean' AND A.[SLA Age] > 30 AND C.[Claim Paid Amount] > 0.01 AND C.[Claim Interest Amount] > 0 THEN 'Yes'\n    WHEN B.[Clean Indicator] = 'Clean' AND A.[SLA Age] > 30 AND C.[Claim Paid Amount] > 0.01 AND C.[Claim Interest Amount] <= 0 THEN 'No'\nEND                    AS \"Interest Paid Correctly\"\n\nFROM [Claims SLA Calculation] AS A\nJOIN [Claim] AS B ON A.[CLAIM_ID] = B.[Claim ID]\nLEFT JOIN [Claim Amount] AS C ON B.[Claim ID] = C.[CLAIM_ID]"
